INSERT INTO `projects_screens` (`id`, `id_project`, `is_video`, `video_url`, `screen_shot`, `sorting`, `title`, `description`, `created_at`, `updated_at`) VALUES

(1, 1, 0, '', 'images/projects/HCMS/HCMS_history.jpg', 3, 'Tabulky dat', 'Jedna z tabulek pro zobrazení dat aplikace. Umožňuje export do běžných formátů (Excel, PDF, ...), stránkování, řazení a filtrování.', '2023-02-07 10:50:11', '2023-02-07 10:50:11'),

(2, 1, 0, '', 'images/projects/HCMS/hcms_tablet_screen.jpg', 4, 'Tablet', 'Část aplikace používaná na tabletu. Pracovník zde obdrží instrukci, podle které postupuje.', '2023-02-07 11:04:21', '2023-02-07 11:04:21'),

(3, 1, 0, '', 'images/projects/HCMS/HCMS__main_page_full.jpg', 2, 'Hlavní obrazovka', 'Hlavní stránka aplikace, kde uživatelé zadají číslo dílu a ihned zde vidí veškeré potřebné informace potřebné k rychlému a efektivnímu zpracování zadaného úkolu.', '2023-02-07 11:10:50', '2023-02-07 11:10:50'),

(5, 24, 0, '', 'images/projects/FLR/FRLcreator_main_page.jpg', 1, 'Zadání parametrů', 'Hlavní stránka na které probíhá zvolení veškerých potřebných parametrů k určení toho, jaké listy se mají generovat.', '2023-02-13 23:37:05', '2023-02-13 23:37:06'),

(6, 24, 0, '', 'images/projects/FLR/FRLcreator_pdf_list.jpg', 2, 'Výstup', 'Vygenerovaný regálový list.', '2023-02-13 23:45:52', '2023-02-13 23:45:52'),

(7, 25, 0, '', 'images/projects/picker/picker_introduction.jpg', 1, 'Hlavní obrazovka', 'Veškeré instrukce k provedení operace na jedné obrazovce.', '2023-02-21 22:29:45', '2023-02-21 22:29:45'),

(8, 25, 0, '', 'images/projects/picker/picker_main_page_h.jpg', 2, 'Responzivní', 'V zobrazení na výšku se prvky přeskládají, aby se vešly na obrazovku.', '2023-02-21 22:35:17', '2023-02-21 22:35:17'),

(9, 25, 0, '', 'images/projects/picker/picker_call_abn.jpg', 3, 'Když dojde k problému', 'Zde probíhá předání informace pro team leadera apod..', '2023-02-21 22:36:49', '2023-02-21 22:36:49'),

(10, 25, 0, '', 'images/projects/picker/picker_TLscreen.jpg', 4, 'Summary', 'Obrazovka team leadera, kde má možnost sledovat stavy jednotlivých procesů.', '2023-02-21 22:39:18', '2023-02-21 22:39:18'),

(11, 25, 0, '', 'images/projects/picker/picker_processMaster.jpg', 5, 'Nastavení', 'Jedna z admin obrazovek pro nastavování aplikace.', '2023-02-21 22:39:18', '2023-02-21 22:39:18'),

(12, 2, 0, '', 'images/projects/itwebtech/pilire_itwebtech.jpg', 2, 'Pilíře', 'Mé základní pilíře při vývoji aplikací.', '2023-02-27 17:40:47', '2023-02-27 17:40:47'),

(13, 26, 0, '', 'images/projects/elektro-srnak/elektro_srnak_introduction.jpg', 1, 'elektro-srnak', 'Na web se můžete podívat přímo <a href=\"https://www.elektro-srnak.cz\" target=\"_blank\">www.elektro-srnak.cz</a>', '2023-03-11 19:04:59', '2023-03-11 19:04:59'),

(14, 1, 0, '', 'images/projects/HCMS/HCMS_domain_model.jpg', 5, 'Doménový model', 'Každému projektu předchází důkladná analýza.', '2023-03-18 14:52:09', '2023-03-18 14:52:09'),

(15, 1, 0, '', 'images/projects/HCMS/HCMS_functions_model.jpg', 6, 'Funkční model', 'Funkční model aplikace je též před-vývojovou součástí.', '2023-03-18 14:55:39', '2023-03-18 14:55:39'),

(16, 1, 0, '', 'images/projects/HCMS/HCMS_usecases.jpg', 7, 'Use cases', 'Jak bude aplikace používaná vím a zohledním při vývoji díky sestavení use case diagramu.', '2023-03-18 14:57:03', '2023-03-18 15:16:17'),

(17, 2, 0, '', 'images/projects/itwebtech/itwebtech_seo.jpg', 1, 'SEO', 'Optimalizovat SOE je základem pro každou webovou stránku. Toto je test stránek itwebtech.cz z 23.3.2023 provedený na webu seotest.seolight.cz', '2023-03-23 21:17:30', '2023-03-23 21:27:03'),

(18, 27, 0, '', 'images/projects/excel/FLR_backup_case2.jpg', 1, 'FLR backup 2', 'Apka sloužící jako záloha v případě výpadku hlavní aplikace. Po jednotlivých krocích provede uživatele a postupně vytvoří potřebné data a dokumenty k vytištění pro to, aby mohly být díly dodávány na montážní linku.', '2023-03-28 22:09:13', '2023-03-28 22:09:13'),

(19, 27, 0, '', 'images/projects/excel/FLR_backup_case1.jpg', 2, 'FLR backup 1', 'Na základě vstupních parametrů zadaných uživatelem vytvoří csv soubor s daty potřebnými pro další operace.', '2023-03-28 22:10:45', '2023-03-28 22:10:45'),

(20, 27, 0, '', 'images/projects/excel/address_data.jpg', 3, 'Address data', 'Popis použití malé apky, která nakombinuje data z různých zdrojů, aby z nich vytvořila validní informace k jednotlivým dílům.', '2023-03-28 22:12:49', '2023-03-28 22:12:49'),

(21, 27, 0, '', 'images/projects/excel/pdf_kanban.jpg', 4, 'Kanban', 'Programoval jsme také samostatnou apku která ze vstupních dat vytvoří instrukční kanbany v pdf formátu k vytištění.', '2023-03-28 22:14:13', '2023-03-28 22:14:13'),

(22, 27, 0, '', 'images/projects/excel/process_combinations.jpg', 5, 'Kombinace procesů', 'Na základě nahraných dat se zde vizualizuje množství materiálu dodávané na jednotlivá místa linek. Slouží k plánování dodávek tak, aby nedocházelo v jeden čas dodávkám na jedno místo od více procesů.', '2023-03-28 22:17:59', '2023-03-28 22:17:59'),

(23, 27, 0, '', 'images/projects/excel/report.jpg', 6, 'Report', 'Tento nástroj vytvoří z Excel reportu pdf soubor a odešle ho na definované emailová adresy. Citlivá data jsou zde skryta.', '2023-03-28 22:19:57', '2023-03-28 22:19:57'),

(24, 29, 0, '', 'images/projects/strechyzajic/strechyzajic_introduction.jpg', 1, 'Střechy Zajíc', 'Na web se můžete podívat přímo <a href=\"https://strechyzajic.cz\" target=\"_blank\">www.strechyzajic.cz</a>rn<br><br>rnDůkaz o tom, že jsem ho tvořil já, najdete v patičce webu úpně dole.', '2023-05-25 21:12:17', '2023-05-25 21:12:17'),

(25, 30, 1, 'https://www.youtube.com/watch?v=_rfmLb9x-N0', 'images/projects/pitarena/video-pitbike-akademie.jpg', 10, 'Pitbike akademie', 'Video pro propagaci na sociální síti Facebook.', '2023-08-03 06:22:20', '2023-08-03 06:22:20'),

(26, 31, 0, '', 'images/projects/pitarena/pitarena_introduction.jpg', 99, 'Ukázaná platí', 'Na web se můžete podívat přímo <a href=\"https://pitarena.cz/\" target=\"_blank\">pitarena.cz</a>rn<br><br>rnDůkaz o tom, že jsem ho tvořil já, najdete v patičce webu úpně dole.', '2023-07-20 15:48:16', '2025-01-02 11:58:10'),

(27, 32, 0, '', 'images/projects/pitarena/pitarena_cedule.jpg', 3, 'Reklamní cedule', 'Vytvoření designu a podkladových souborů pro velkoformátový tisk reklamní cedule nad servis.', '2023-08-08 21:07:07', '2023-08-08 21:07:07'),

(28, 33, 1, 'https://www.youtube.com/embed/GzHQKOqqJW0', 'images/projects/itwebtech/video_delejme_animace.jpg', 10, 'Upoutání pozornosti', 'Může takovéto video upoutat něčí pozornost?<br>rnAsi budete souhlasit, že něčí ano.rn<br>rnRozhodně i při tvorbě videa vždy musíme myslet no to, koho chceme zaujmout.', '2023-10-03 14:44:55', '2023-10-03 14:44:55'),

(29, 34, 0, '', 'images/projects/vanspedition/vanspedition_introduction.webp', 1, 'VAN spedition', 'Na web se můžete podívat přímo <a href=\"https://www.vanspedition.com\" target=\"_blank\">www.vanspedition.com</a>', '2023-11-12 09:25:14', '2023-11-17 09:25:14'),

(30, 35, 0, '', 'images/projects/yolk/unica_introduction.webp', 1, 'Pacientský portál kliniky Unica', 'Na tomto projektu pravidelně dělám zejména změny v rozsáhlém dotazníku pro pacienty. Který je součástí webu jako samoctatná aplikace.rn<br>rn<a href=\"https://www.unica.cz/\" target=\"_blank\">www.unica.cz</a>', '2023-12-01 19:21:22', '2024-06-28 18:21:22'),

(31, 35, 0, '', 'images/projects/yolk/reproclinic_introduction.webp', 99, 'Web reprodukční kliniky', 'Velmi rozsáhlé webové stránky, kde je potřeba často upravovat a inovovat. Jsou primárně vystaveny na WordPressu, ale hodně věcí se tam kóduje ručně, protože jsou na míru (řešení, které samotný WP neumožňuje).rn<br>rn<a href=\"https://reproclinic.com/\" target=\"_blank\">reproclinic.com</a>rn', '2024-01-02 19:57:22', '2024-06-28 18:57:22'),

(32, 37, 1, 'https://youtube.com/g4sRoKhe-8I?si=Sk2USy9Gz-xkKdTW', 'images/projects/realitacky/logo_realitacky_v_akci.png', 1, 'Logo pro Realiťačky', 'Logo musí být snadno zapamatovatelné a odlišné od konkurence. Pokud možno jednoduché a ve vektorovém formátu pro neměnnou kvalitu v jakékoli velikosti.', '2024-01-28 07:22:20', '2024-01-28 07:22:20'),

(33, 38, 0, '', 'images/projects/pitarena/original_clanku_pro_standu.jpg', 1, 'Článek v původním znění.', 'Toto je původní verze článku, jak jsem ho napsal a je na webu klienta zde rn<a href=\"https://pitarena.cz/blog/ycf-cup-posouva-pitbike-motokros-v-pred\" target=\"_blank\">pitarena.cz/blog/ycf-cup-posouva-pitbike-motokros-v-pred</a>.', '2024-02-01 09:06:33', '2024-02-02 09:06:33'),

(34, 38, 0, '', 'images/projects/pitarena/clanek_motorkari_cz_mobile.jpg', 2, 'Článek s úpravami pro Motorkari.cz', 'Zde je článek, který poupravil zkušený redaktor rn<a href=\"https://www.motorkari.cz/motosport/motocross/ostatni/ycf-cup-motokrosovych-pitbiku-si-ziskava-srdce-jezdcu-i-fanousku-50728.html\" target=\"_blank\">motorkari.cz/motosport/motocross/ostatni/ycf-cup-motokrosovych-pitbiku-si-ziskava-srdce-jezdcu-i-fanousku-50728.html</a>.', '2024-02-01 09:06:33', '2024-02-02 09:06:33'),

(35, 39, 0, '', 'images/projects/vpindustry/vpindustry_web_00.webp', 1, 'Design návštěvnost nepřivede', 'Výše ukazuji porovnání webu PŘED a PO, ale design není to na co bychom se měli v tomto porovnání soustředit. Design návštěvnost nepřivede (pomáhá návštěvnost udržet).rn<br> <strong>Rozdíl je v obsahu.</strong> Zatímco předtím existoval seznam produktů prakticky bez ničeho a ani po kliknutí na daný produkt jste se více informací nedozvěděli, tak nově jsem vytvořil ke každému produktu hodnotný obsah. Nejen popis optimalizovaný pro pro lidi i  vyhledávače, ale také videa, různé ukázky a další.rn<br>rnWeb je tak připravený pro růst, ale bez následné kontinuální práce s obsahem se návštěvnost sama od sebe výrazně nezvedne.', '2024-06-28 16:40:46', '2024-06-28 16:40:46'),

(36, 39, 1, 'https://youtu.be/Nuz856_u7f8', 'images/projects/vpindustry/vpindustry_web_02.webp', 7, 'Oživení', 'Oživit stránku můžete například přidáním takovéto animace na místo pouhé nudné fotografie.', '2024-06-28 16:40:46', '2024-06-28 16:40:46'),

(37, 39, 0, '', 'images/projects/vpindustry/vpindustry_web_03.webp', 99, 'Prohlédněte si web', 'Realizaci najdete na <a href=\"https://vpindustry.cz/\" target=\"_blank\">vpindustry.cz</a>rn<br>rn(autorství je uvedené v patičce webu).', '2024-07-01 16:40:46', '2024-06-28 16:40:46'),

(38, 39, 0, '', 'images/projects/vpindustry/vpindustry_web_04.webp', 3, 'Stanovení cílů', 'Ještě před samotným uzavřením zakázky jsem na základě úvodní konzultace důkladně analyzoval současný stav a vyhodnotil potenciál.rn<br>rnVýsledkem byla rozsáhlá prezentace, na které jsem přehledně demonstroval nejen současný stav, ale hlavně <strong>splnitelné cíle</strong>, které klient může očekávat.', '2024-07-01 16:40:46', '2024-06-28 16:40:46'),

(39, 39, 0, '', 'images/projects/vpindustry/vpindustry_web_05.webp', 4, 'Analýza konkurence', 'Do analýzy konkurence jsem zahrnul 27 konkurenčních webů se zaměřením na 6 největších konkurentů.', '2024-07-01 16:40:46', '2024-06-28 16:40:46'),

(40, 39, 0, '', 'images/projects/vpindustry/vpindustry_web_06.webp', 5, 'Analýza klíčových slov', 'Poctivá analýza klíčových slov je něco bez čeho se neobejde žádný pořádný web. ', '2024-07-01 16:40:46', '2024-06-28 16:40:46'),

(41, 39, 0, '', 'images/projects/vpindustry/vpindustry_web_07.webp', 6, 'Sledování výkonu', 'Spuštěním webu to ideálně nekončí. V dalším kroku dává smysl pravidelně vyhodnocovat vyhledávání, pozice a chování uživatelů a na základě dat rozvíjet obsah (nové/rozšířené stránky, články, interní prolinkování, linkbuilding).rn<br>V tomto projektu jsem dodal připravený základ a měření. Navazující růstová fáze se zatím nerealizovala.', '2024-07-01 16:40:46', '2024-06-28 16:40:46'),

(42, 40, 0, '', 'images/projects/choccoboard/choccoboard_00.webp', 1, 'Jen přihlášení uživatelé', 'Samozřejmostí pro takovou aplikaci je přístup pouze pro autorizované osoby.', '2024-09-04 16:22:46', '2024-09-04 16:22:46'),

(43, 40, 0, '', 'images/projects/choccoboard/choccoboard_01.webp', 2, 'Vše na jedné obrazovce', 'Pokud je to možné je vždy nejlepší mít vše na jedné obrazovce, abyste nemuseli nikde po aplikaci zbytečně cestovat. A hlavně máte vše ihned ke vzájemnému porovnání.', '2024-09-04 16:23:12', '2024-09-04 16:23:12'),

(44, 40, 0, '', 'images/projects/choccoboard/choccoboard_02.webp', 3, 'Přizpůsobení pro mobilní telefon', 'Obrovskou výhodou webových aplikací je také dostupnost na jakémkoli zařízení s internetovým prohlížečem. Díky přizpůsobenému zobrazení pro mobilní telefony a tablety je práce s aplikací dostupná i při čekání na autobus &#128077;', '2024-09-04 16:23:12', '2024-09-04 16:23:12'),

(45, 40, 0, '', 'images/projects/choccoboard/choccoboard_03.webp', 4, 'Nepřeberné možnosti', 'Chcete třeba vědět, která směna prodala minulý týden více zmrzlinových pohárů? Stačí si vybrat a kliknout. ', '2024-09-04 16:32:05', '2024-09-04 16:32:05'),

(46, 41, 0, '', 'images/projects/realitackyvakci/realitackyvakci_00.webp', 1, 'Prezentace nemovitostí', 'Na webech realitních kanceláří si návštěvník většinou musí vystačit s kupou menších fotografií. Zde jsem pro lepší a odlišný dojem zvolil u každé nemovitosti vlastní hero sekci, kde je možnost kvalitními fotografiemi ihned <strong>zasáhnout emoce potenciálního kupce</strong>.', '2024-09-17 06:22:46', '2024-09-17 06:22:46'),

(47, 41, 0, '', 'images/projects/realitackyvakci/realitackyvakci_02.webp', 2, 'Doplňková navigace', 'Stránky s nabízenými nemovitostmi obsahují sekundární navigaci, která <strong>usnadňuje a urychluje orientaci na stránce</strong>.<br>rnNechybí ani odkaz na kontaktní formulář (na téže stránce) s předvyplněnými informacemi.', '2024-09-17 06:22:46', '2024-09-17 06:28:46'),

(48, 41, 0, '', 'images/projects/realitackyvakci/realitackyvakci_03.webp', 3, 'Tvorba značky', 'Na začátku nebyl název ani logo.<br>rnI když se klientky nakonec rozhodly jít jinou cestou <i>(volil bych zejména jiný název - kratší a univerzálnější, který bych podpořil vhodným sloganem)</i>, poskytl jsem jim poradenství v oblasti <strong>tvorby brandu (značky), podle zásad známého tvůrce brandů Michala Pastiera</strong>.<br><br>rnVytvořil jsem také originální logo pro novou značku, které není zaměnitelné s žádným z nám známých konkurentů.<br>rn<img src=\"../../assets/img/brands/realitackyvakci_new.png\">', '2024-09-17 06:22:46', '2024-09-17 06:38:46'),

(49, 41, 0, '', 'images/projects/realitackyvakci/realitackyvakci_04.webp', 4, 'Úpravy ve vlastních rukách', 'Web obsahuje přehlednou administrační část. V té si klientky mohou po přihlášení psát články na blog a upravovat veškeré nabídky i poptávky.<br><br>rnToto nemusí být ideální volbou pro každého <i>(ať už z časových důvodů, nebo kvůli technickým aspektům)</i>, ale je to určitě vhodné, pokud potřebujete často a rychle <strong>přidávat nebo měnit obsah na webu bez asistence vývojáře</strong>.', '2024-09-17 06:22:46', '2024-09-17 06:38:46'),

(50, 41, 0, '', 'images/projects/realitackyvakci/realitackyvakci_05.webp', 5, 'Rezervační systém', 'Pro tento projekt jsem zvolil napojení na rezervační systém Reservanto, který je v této variantě dostačující i <strong>ve variantě zdarma</strong>.<br>rnSystém jsem kompletně nastavil a seznámil jsem klientky s používáním.<br><br>rnMají tak k dispozici nástroj pro řízení času určeného na schůzky s klienty, kterým <strong>stačí jen kliknout na tlačítko na jejich webu</strong> a vybrat si vyhovující den a čas schůzky.', '2024-09-17 06:42:46', '2024-09-17 06:58:46'),

(51, 41, 0, '', 'images/projects/realitackyvakci/realitackyvakci_06.webp', 6, 'Výzva a řešení', '<strong>Výzva:</strong> Omezující množství poskytnutých kvalitních fotografií.<br>rn<strong>Řešení:</strong> Kombinace poskytnutých fotografií s profesionálními snímky z fotobanky zajistila vizuální kvalitu webu.<br><br>rnNapř.:<br>rnKdyby za stolem na tomto snímku seděly klientky, bylo by to určitě lepší. Kvalitní foto z placené fotobanky je ale stále lepší, než nemít foto žádné, nebo extrémně nekvalitní.<br>rnChybějící fotografie nemovitostí jsem v kódu nahradil avatarem s informací, že <i>\"foto ještě nebylo přidáno\"</i>, aby web nepůsobil rozbitým dojmem.', '2024-09-17 10:18:46', '2024-09-17 10:18:46'),

(52, 41, 0, '', 'images/projects/realitackyvakci/realitackyvakci_07.webp', 7, 'Tvorba obsahu', 'Vytvořil jsem také dva úvodní <strong>články do blogu</strong> a další textový obsah. Klientky si chtějí blog psát osobně, ale zatím se k tomu z časových důvodů nedostaly. Proto jsem nabídl vytvoření úvodních článků, které si mohou později přizpůsobit.', '2024-09-17 10:18:46', '2024-09-17 10:18:46'),

(53, 41, 0, '', 'images/projects/realitackyvakci/realitackyvakci_web_01.webp', 8, 'Podívejte se na web', 'Na web se můžete podívat přímo <a href=\"https://realitackyvakci.cz/\" target=\"_blank\">realitackyvakci.cz</a>rn<br><br>rnDůkaz o tom, že jsem ho tvořil já, najdete v patičce webu úpně dole.', '2024-09-17 10:30:46', '2024-09-17 10:32:46'),

(54, 1, 1, 'https://youtu.be/Oq0fpGZBLfk?si=LvQ7IQR2EcL-IPFm', 'images/projects/HCMS/HCMS__main_page_full.jpg', 1, 'Video prezentace projeku', 'Shrnutí základních informací o této webové aplikaci najdete v tomto videu.', '2024-09-27 10:10:50', '2024-09-27 10:10:50'),

(55, 42, 0, '', 'images/projects/josefopa/josefopa_00.webp', 2, 'Pro všechna zařízeních', 'Tzv. respozivita, tedy to, aby se webová stránka zobrazovala správně na všech zařízeních, je naprostou samozřejmostí.', '2024-10-17 06:22:46', '2024-10-17 06:22:46'),

(56, 42, 0, '', 'images/projects/josefopa/josefopa_01.webp', 1, 'Grafické práce', 'Zde je jen malá <strong>ukázka konceptů</strong>, na cestě za specifickým logem na přání. S profesionálními nástroji jako jsou Adobe Ilustrator, Photoshop, Canva a další, keteré ke své práci využívám, to není žádný problém.', '2024-10-17 06:22:46', '2024-10-17 06:22:46'),

(57, 42, 0, '', 'images/projects/josefopa/josefopa_02.webp', 3, 'Vizitky', 'Klient měl také požadavek na vytvoření vizitek, které budou vizuálně v souladu s webovými stránkami.rn<br>Nechybí QR kódy pro rychlé načtení webu, či uložení kontaktů.', '2024-10-17 07:22:46', '2024-10-17 07:22:46'),

(58, 42, 0, '', 'images/projects/josefopa/josefopa_web_01.webp', 4, 'Prohlédněte si web', 'Na web se můžete podívat živě na <a href=\"https://josefopa.de/\" target=\"_blank\">josefopa.de</a>rn<br><br>rnDůkaz o tom, že jsem ho tvořil já, najdete v patičce webu úpně dole.', '2024-10-17 08:22:46', '2024-10-17 08:22:46'),

(59, 43, 1, 'https://youtu.be/pc6rW91_0ek?si=dDWxeX3f8O2Q0vp8', 'images/projects/kempveselka/videoukazka_kempveselka.webp', 1, 'Videoukázka webu', 'V tomto krátkém videu si můžete prohlédnou vzhled webu v podobě na počítači i na mobilu.', '2024-12-21 09:22:46', '2024-12-21 09:22:46'),

(60, 43, 0, '', 'images/projects/kempveselka/kempveselka_web_01.webp', 99, 'Prohlédněte si web osobně', 'Na web se můžete podívat živě na <a href=\"https://kempveselka.cz/\" target=\"_blank\">kempveselka.cz</a>rn<br><br>rnDůkaz o tom, že jsem ho tvořil já, najdete v patičce webu úpně dole.', '2024-12-21 09:22:46', '2024-12-21 09:22:46'),

(61, 31, 0, '', 'images/projects/pitarena/pitarena_01.webp', 1, 'Pořád volají další zájemci', '<p>\"Ondro - neustále mi volají lidi, že si nás našli na Googlu a chtějí k nám přijet - ten web fakt funguje!\"</p>rn<p>I takovéto \"problémy\" mohou nastat :) <br>Zde k tomu stačilo jen několik článků, které jsem vytvořil na téma \"motokros a děti\".</p>', '2023-07-20 15:48:16', '2025-01-02 09:58:10'),

(62, 31, 0, '', 'images/projects/pitarena/pitarena_02.webp', 2, 'Zjednodušte si práci', '<p>Web obsahuje několik klíčových formulářů, které pomáhají zvyšovat konverze a usnadňují zpracování poptávek.</p>rn<p>Aby mohl klient například zaregistrovat nového závodníka nebo rezervovat zapůjčení motorky, potřebuje znát některé informace. Díky přehledným formulářům je předání informací i jejich správa jednoduchá.</p>', '2025-01-02 08:48:16', '2025-01-02 09:58:10'),

(63, 31, 0, '', 'images/projects/pitarena/pitarena_03.webp', 3, 'Prodávejte online', '<p>Klient v průběhu roku nabízí různé poukazy, vstupenky na akce a podobně. Na vše je potřeba vystavit faktůru, zaslat potvrzovací email a vést přehledný systém objednávek.</p>rn<p>Napojením na prodejní systémy jako jsou SimpleShop nebo Reservanto, jsem celý proces automatizoval.</p>', '2025-01-02 08:48:16', '2025-01-02 09:58:10'),

(64, 43, 0, '', 'images/projects/kempveselka/kempveselka_web_02.webp', 4, 'Perfektní rychlost i SEO', 'Web dosahuje perfektních měřitelných výsledků v oblasti výkonu, technického SEO, přístupnosti i best practice (bezpečnost a kvalita kódu).rn<br>rnVýsledku jsem dosáhl zejména díky tomu, že web jsem od základu programoval vlastním kódem (není zahrnuto v ceně - jednalo se o bonus v rámci akce).rn<br><br>rnNejnižší hodnoty (84 ze 100) dosahuje výkon na mobilech s velmi pomalým připojením k internetu. Toto by se dalo také vylepšit, ale bylo by to na úkor uživatelského dojmu a zde by to webu spíše uškodilo.', '2025-01-07 06:02:46', '2025-01-07 06:02:46'),

(65, 43, 0, '', 'images/projects/kempveselka/kempveselka_web_03.webp', 2, 'Cíle projektu', '<ol>rn<li>Jednoduchý, ale profesionální vzhled, který odpovídá atmosféře kempu.</li>rn<li>Web přizpůsobený pro všechna zařízení.</li>rn<li>Rychlý přístup k informacím o ubytování a službách.</li>rn<li>Jasné tlačítko pro okamžitou telefonickou rezervaci.</li>rn<li>Vytvořit logo, které bude kemp prezentovat.</li>rn</ol>', '2025-01-07 06:02:46', '2025-01-07 06:02:46'),

(66, 43, 0, '', 'images/projects/kempveselka/kempveselka_web_04.webp', 3, 'Jak jsem postupoval', '<ol>rn<li>Analýza konkurence a top příkladů ze zahraničí: „Provedl jsem důkladnou analýzu konkurenčních kempů v regionu, abych identifikoval jejich silné a slabé stránky.“ *</li>rn<li>Návrh designu: „Vytvořil jsem několik návrhů, které reflektují atmosféru kempu a oslovují cílovou skupinu.“ *</li>rn<li>Implementace a testování: „Web byl pečlivě testován na různých zařízeních a prohlížečích pro zajištění bezchybné funkčnosti.“ *</li>rn</ol>rn<ul>rn<li>* potvrzení s klientem</li>rn</ul>', '2025-01-07 09:02:46', '2025-01-07 09:02:46');
